```python
def first_or_default(items, default=None):
    if not items:
        return default
    return items[0]
```

```python
def average(nums):
    if not nums:
        return 0
    return sum(nums) / len(nums)
```

```python
def safe_lookup(d, key, default=None):
    if d is None:
        return default
    return d.get(key, default)
```

```python
def safe_index(lst, i):
    if not isinstance(lst, list):
        return None
    if i < -len(lst) or i >= len(lst):
        return None
    return lst[i]
```

```python
def chunk(lst, size):
    if size <= 0:
        return []
    if not lst:
        return []
    return [lst[i:i + size] for i in range(0, len(lst), size)]
```

```python
def clamp(value, lo, hi):
    if lo > hi:
        lo, hi = hi, lo
    if value < lo:
        return lo
    if value > hi:
        return hi
    return value
```

```python
def median(nums):
    if not nums:
        return None
    s = sorted(nums)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    return (s[n // 2 - 1] + s[n // 2]) / 2
```

```python
def unique_pairs(nums):
    if len(nums) < 2:
        return []
    seen = set()
    pairs = []
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            key = (min(nums[i], nums[j]), max(nums[i], nums[j]))
            if key not in seen:
                seen.add(key)
                pairs.append(key)
    return pairs
```

```python
def strip_safe(s):
    if s is None:
        return ''
    if not isinstance(s, str):
        s = str(s)
    return s.strip()
```

```python
def bin_count(nums):
    counts = {}
    if not nums:
        return counts
    for n in nums:
        counts[n] = counts.get(n, 0) + 1
    return counts
```

```python
def reverse_string(s):
    if s is None:
        return None
    if not isinstance(s, str):
        s = str(s)
    return s[::-1]
```

```python
def count_substring(s, sub):
    if not sub:
        return 0
    return s.count(sub)
```

```python
def safe_min(nums, default=None):
    if not nums:
        return default
    return min(nums)
```

```python
def intersect(a, b):
    if not a or not b:
        return []
    return sorted(set(a) & set(b))
```

```python
def safe_int(s, default=0):
    if s is None:
        return default
    try:
        return int(s)
    except (ValueError, TypeError):
        return default
```

```python
def flatten_once(nested):
    if not nested:
        return []
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(item)
        else:
            result.append(item)
    return result
```

```python
def partition(nums, predicate):
    matches = []
    non_matches = []
    for n in nums:
        if predicate(n):
            matches.append(n)
        else:
            non_matches.append(n)
    return matches, non_matches
```

```python
def dedupe(items):
    seen = set()
    result = []
    for x in items:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result
```

```python
def only_digits(s):
    if not s:
        return ''
    return ''.join(c for c in s if c.isdigit())
```

```python
def nested_get(d, keys, default=None):
    current = d
    for k in keys:
        if not isinstance(current, dict):
            return default
        if k not in current:
            return default
        current = current[k]
    return current
```

```python
def pad_list(lst, length, fill=0):
    if length <= 0:
        return []
    if len(lst) >= length:
        return lst[:length]
    return lst + [fill] * (length - len(lst))
```

```python
def group_by(items, key_fn):
    groups = {}
    for item in items:
        key = key_fn(item)
        if key not in groups:
            groups[key] = []
        groups[key].append(item)
    return groups
```

```python
def deep_copy_simple(obj):
    if isinstance(obj, list):
        return [deep_copy_simple(item) for item in obj]
    if isinstance(obj, dict):
        return {k: deep_copy_simple(v) for k, v in obj.items()}
    return obj
```

```python
def safe_divmod(a, b):
    if b == 0:
        return (None, None)
    return divmod(a, b)
```

```python
def paginate(items, page, page_size):
    if page < 1 or page_size < 1:
        return []
    start = (page - 1) * page_size
    if start >= len(items):
        return []
    return items[start:start + page_size]
```

```python
def last_n(items, n):
    if n <= 0:
        return []
    if not items:
        return []
    return items[-n:]
```

```python
def safe_max_index(nums):
    if not nums:
        return None
    best_idx = 0
    for i in range(1, len(nums)):
        if nums[i] > nums[best_idx]:
            best_idx = i
    return best_idx
```

```python
def batch_apply(items, fn):
    results = []
    for item in items:
        try:
            results.append((fn(item), None))
        except Exception as e:
            results.append((None, e))
    return results
```

```python
def safe_chain(funcs, value):
    current = value
    for fn in funcs:
        if current is None:
            return None
        current = fn(current)
    return current
```
